/**
 * logo-default.js
 * Embedded copy of the default company logo (downscaled to 256x256
 * to keep this file small -- it's only ever rendered small, in the
 * app header and at 64pt in the PDF) as a base64 data URL.
 * Used as a last-resort fallback for PDF generation when fetching
 * assets/logo/MB.png fails (e.g. the app was opened directly from
 * disk via file:// instead of through a web server, where fetch()
 * of local files is blocked by the browser).
 * Regenerate this file any time assets/logo/MB.png changes by running:
 *   python3 -c "from PIL import Image; import base64,io; im=Image.open('assets/logo/MB.png').convert('RGB').resize((256,256)); b=io.BytesIO(); im.save(b,format='PNG',optimize=True); print('data:image/png;base64,'+base64.b64encode(b.getvalue()).decode())"
 * and pasting the result below.
 */
(function (global) {
  "use strict";
  global.EMBEDDED_DEFAULT_LOGO_BASE64 = "data:image/png;base64,";
})(window);
